    /// <summary>
    /// Maps entity to datasource.
    /// </summary>
    /// <param name = "_entityCtx">
    /// <c>DataEntityRuntimeContext</c>.
    /// </param>
    /// <param name = "_dataSourceCtx">
    /// <c>DataEntityDataSourceRuntimeContext</c>.
    /// </param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

        
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, METInventItemOrderSetup):
                METInventItemOrderSetup metInventItemOrderSetup   =  _dataSourceCtx.getBuffer();
                InventItemInventSetup inventItemInventSetup  = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, InventItemInventSetup)).getBuffer();
                InventItemPurchSetup inventItemPurchSetup = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, InventItemPurchSetup)).getBuffer();

                if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
                {                    
                    metInventItemOrderSetup.InventDimId = inventItemInventSetup.InventDimId;
                    metInventItemOrderSetup.SiteId =  InventDim::find(inventItemInventSetup.InventDimId).InventSiteId;
                }
                else if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
                {
                    if (!metInventItemOrderSetup.SiteId)
                    {
                        metInventItemOrderSetup.SiteId =  InventDim::find(inventItemInventSetup.InventDimId).InventSiteId;
                    }
                }
                metInventItemOrderSetup.CartonPerPallet = metInventItemOrderSetup.CartonPerLayer * metInventItemOrderSetup.Layers;
                this.calculatePalletQty(inventItemPurchSetup, metInventItemOrderSetup);
                break;
        }
        
    }

    /// <summary>
    /// Calculate pallet qty
    /// </summary>
    /// <param name = "_inventItemPurchSetup">InventItemPurchSetup</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    public void calculatePalletQty(InventItemPurchSetup _inventItemPurchSetup, METInventItemOrderSetup _metInventItemOrderSetup)
    {
        UnitOfMeasureSymbol fromUnit, toUnit;
        UnitOfMeasureConversionFactor factor;

        fromUnit = _inventItemPurchSetup.METPurchUnit;

        toUnit = InventTable::find(_inventItemPurchSetup.ItemId).inventTableModuleInvent().UnitId;

        if (!fromUnit || !toUnit)
        {
            factor = 0;
        }
        else if (fromUnit == toUnit)
        {
            factor = 1;
        }
        else
        {
            factor = UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(fromUnit).RecId,
            UnitOfMeasure::findBySymbol(toUnit).RecId,
            EcoResProduct::findByProductNumber(_inventItemPurchSetup.ItemId).RecId).Factor;
        }

        _metInventItemOrderSetup.PalletLayerQty = _metInventItemOrderSetup.CartonPerLayer * factor;
        _metInventItemOrderSetup.PalletQty = _metInventItemOrderSetup.CartonPerPallet * factor;
    }

    /// <summary>
    /// CB409_D365ToPIM
    /// Get temp item pack change boolean value for the items
    /// </summary>
    public static str getTempItemPackChangeBooleanValue()
    {
        str tempItemPackChangeBooleanValue;

        str itemId = SysComputedColumn::returnField(tableStr(InventProductSpecificOrderSettingsV3Entity), dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, InventItemInventSetup), fieldStr(InventItemInventSetup, ItemId));
        str dataAreaIdField = SysComputedColumn::returnField(tablestr(InventProductSpecificOrderSettingsV3Entity), dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, InventItemInventSetup), fieldstr(InventItemInventSetup, DataAreaId));

        tempItemPackChangeBooleanValue = strFmt(@"(SELECT BOOLEANVALUE FROM METItemPackChangeBooleanValueView
                                                   WHERE METItemPackChangeBooleanValueView.ITEMID = %1 AND METItemPackChangeBooleanValueView.DATAAREAID = %2)",
                                                   itemId,
                                                   dataAreaIdField);
        
        
        return TempItemPackChangeBooleanValue;
    }

    /// <summary>
    /// Get coverage warehouse
    /// </summary>
    /// <returns>Query string</returns>
    public static str getCoverageWarehouse()
    {   
        str coverageWarehouse;

        str itemId = SysComputedColumn::returnField(tableStr(InventProductSpecificOrderSettingsV3Entity), dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, InventItemInventSetup), fieldStr(InventItemInventSetup, ItemId));
        str siteId = SysComputedColumn::returnField(tablestr(InventProductSpecificOrderSettingsV3Entity), dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, InventDim), fieldstr(InventDim, InventSiteId));

        coverageWarehouse = strFmt(@"(SELECT ISNULL(STRING_AGG(INVENTLOCATIONID, ', '),'') FROM METReqItemTableInventDimView WHERE ITEMID = %1 AND INVENTSITEID = %2)",itemId,siteId);        
        
        return coverageWarehouse;
    }

        /// <summary>
        /// . This is required to make sure the data from the custom table is available for change tracking.
        /// </summary>
        /// <returns></returns>
        public static Query defaultCTQuery()
        {
            // 1. Get the standard query (which already contains InventItemInventSetup as the root)
            Query query = next defaultCTQuery();

            // 2. CORRECT FIX: Retrieve the EXISTING root datasource. 
            QueryBuildDataSource qbdsRoot = query.dataSourceTable(tableNum(InventItemInventSetup));

            if (qbdsRoot)
            {
                // 3. Add your CUSTOM table (METInventItemOrderSetup) as a CHILD of the root
                QueryBuildDataSource qbdsMET = qbdsRoot.addDataSource(tableNum(METInventItemOrderSetup));

                // 4. Set relations (links ItemId and InventDimId automatically)
                qbdsMET.addLink(fieldNum(InventItemInventSetup, ItemId), fieldNum(METInventItemOrderSetup, ItemId));
                qbdsMET.addLink(fieldNum(InventItemInventSetup, InventDimId), fieldNum(METInventItemOrderSetup, InventDimId));

                // 5. Use OuterJoin so tracking works even if the MET record is missing
                qbdsMET.joinMode(JoinMode::OuterJoin);

                // 6. One2One fetch mode — METInventItemOrderSetup is a 1:1 extension of InventItemInventSetup
                qbdsMET.fetchMode(QueryFetchMode::One2One);
            }

            return query; 
        }
